using Microsoft.VisualStudio.TestTools.UnitTesting;
using Payments;

namespace Payments.Tests;

[TestClass]
public class PaymentGatewayTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new PaymentGateway();
    }

    // ───────────────────────────── ChargeAsync ─────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidCardAndAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(result.ChargeId));
    }

    [TestMethod]
    public async Task ChargeAsync_MinimumAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 0.01m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_LargeAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 999_999.99m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsOrFails()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync("tok_valid_visa", 0m));
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ThrowsOrFails()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync("tok_valid_visa", -10m));
    }

    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentNullException>(
            () => _gateway.ChargeAsync(null!, 25.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyCardToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync("", 25.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_ReturnsUniqueChargeIds()
    {
        var result1 = await _gateway.ChargeAsync("tok_visa_1", 10m);
        var result2 = await _gateway.ChargeAsync("tok_visa_2", 20m);

        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId);
    }

    // ───────────────────────────── RefundAsync ─────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccess()
    {
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 50m);
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(refund.RefundId));
    }

    [TestMethod]
    public async Task RefundAsync_InvalidChargeId_ReturnsFalseOrThrows()
    {
        // Depending on implementation, this may return Success=false or throw.
        // Adjust the assertion once the implementation is in place.
        try
        {
            var result = await _gateway.RefundAsync("chg_nonexistent");
            Assert.IsFalse(result.Success);
        }
        catch (Exception ex) when (ex is ArgumentException or InvalidOperationException)
        {
            // Acceptable — implementation chose to throw for unknown charges.
        }
    }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentNullException>(
            () => _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync(""));
    }

    [TestMethod]
    public async Task RefundAsync_DuplicateRefund_ReturnsFalseOrThrows()
    {
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 30m);
        await _gateway.RefundAsync(charge.ChargeId);

        // Second refund on the same charge should fail or throw.
        try
        {
            var duplicate = await _gateway.RefundAsync(charge.ChargeId);
            Assert.IsFalse(duplicate.Success);
        }
        catch (InvalidOperationException)
        {
            // Acceptable — implementation prevents double-refund.
        }
    }
}

